const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.1/budget_line_items',
  headers: {'content-type': 'application/json'},
  body: {
    project_id: 12345,
    budget_line_item: {
      wbs_code_id: 67890,
      original_budget_amount: '10000.00',
      uom: 'hours',
      quantity: 250.5,
      unit_cost: 123.5,
      calculation_strategy: 'manual'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.1/budget_line_items"),
    Content = new StringContent("{\"project_id\":12345,\"budget_line_item\":{\"wbs_code_id\":67890,\"original_budget_amount\":\"10000.00\",\"uom\":\"hours\",\"quantity\":250.5,\"unit_cost\":123.5,\"calculation_strategy\":\"manual\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

